const submittedName = $('Model Name Form').first().json['Model name'];
const query = String(submittedName ?? '').trim();
const catalog = $input.first().json;
const matches = [];

for (const [providerId, provider] of Object.entries(catalog)) {
  for (const [modelId, model] of Object.entries(provider.models ?? {})) {
    const idMatches = modelId.toLowerCase() === query.toLowerCase();
    const nameMatches = String(model.name ?? '').toLowerCase() === query.toLowerCase();
    if (idMatches || nameMatches) {
      matches.push({
        modelId,
        modelName: model.name ?? modelId,
        providerId,
        providerName: provider.name ?? providerId,
      });
    }
  }
}

const result = {
  submittedName: query,
  valid: matches.length > 0,
  matches,
};

return [{ json: { ...result, agentInput: JSON.stringify(result) } }];
